use Zwii\Cms\Helper; trait PageContent { public function getPage($page, $lang) { if ( $this->getData(['page', $page, 'content']) !== '' && file_exists(self::DATA_DIR . $lang . '/content/' . $this->getData(['page', $page, 'content'])) ) { return file_get_contents(self::DATA_DIR . $lang . '/content/' . $this->getData(['page', $page, 'content'])); } else { return 'Aucun contenu trouvé.'; } } public function setPage($page, $value, $lang) { return $this->secure_file_put_contents(self::DATA_DIR . $lang . '/content/' . $page . '.html', $value); } public function deletePage($page, $lang) { return unlink(self::DATA_DIR . $lang . '/content/' . $this->getData(['page', $page, 'content'])); } public function getHierarchy($parentId = null, $onlyVisible = true, $onlyBlock = false) { $hierarchy = $onlyVisible ? $this->hierarchy['visible'] : $this->hierarchy['all']; $hierarchy = $onlyBlock ? $this->hierarchy['bar'] : $hierarchy; if ($parentId) { if (array_key_exists($parentId, $hierarchy)) { return $hierarchy[$parentId]; } else { return []; } } else { return $hierarchy; } } private function buildHierarchy() { $pages = Helper::arrayColumn($this->getData(['page']), 'position', 'SORT_ASC'); foreach ($pages as $pageId => $pagePosition) { if ( $this->getData(['page', $pageId, 'parentPageId']) === '' and ($this->getData(['page', $pageId, 'role']) === self::ROLE_VISITOR or ($this->isConnected() === true and ($this->getUser('role') * self::MAX_PROFILS + $this->getUser('profil')) >= ($this->getData(['page', $pageId, 'role']) * self::MAX_PROFILS + $this->getData(['page', $pageId, 'profil'])))) ) { if ($pagePosition !== 0) { $this->hierarchy['visible'][$pageId] = []; } if ($this->getData(['page', $pageId, 'block']) === 'bar') { $this->hierarchy['bar'][$pageId] = []; } $this->hierarchy['all'][$pageId] = []; } } foreach ($pages as $pageId => $pagePosition) { if ( $parentId = $this->getData(['page', $pageId, 'parentPageId']) and ( ( $this->getData(['page', $pageId, 'role']) === self::ROLE_VISITOR and $this->getData(['page', $parentId, 'role']) === self::ROLE_VISITOR ) or ( $this->isConnected() === true and $this->getUser('role') * self::MAX_PROFILS + $this->getUser('profil') ) >= ($this->getData(['page', $pageId, 'role']) * self::MAX_PROFILS + $this->getData(['page', $pageId, 'profil'])) ) ) { if ($pagePosition !== 0) { $this->hierarchy['visible'][$parentId][] = $pageId; } if ($this->getData(['page', $pageId, 'block']) === 'bar') { $this->hierarchy['bar'][$pageId] = []; } $this->hierarchy['all'][$parentId][] = $pageId; } } } private function tinyMcePages() { $parents = []; $rewrite = (Helper::checkRewrite()) ? '' : '?'; foreach ($this->getHierarchy() as $parentId => $childIds) { if ($this->getData(['page', $parentId, 'parentPageId']) !== '') { continue; } if ($this->getData(['page', $parentId]) && $this->getData(['page', $parentId, 'block']) !== 'bar') { $pageEntry = [ 'title' => html_entity_decode($this->getData(['page', $parentId, 'title']), ENT_QUOTES), 'value' => $rewrite . $parentId, 'menu' => [] ]; $this->addTinyMceChildren($pageEntry['menu'], $childIds, $rewrite, 1); $parents[] = $pageEntry; } } $children = []; $children[] = [ 'title' => 'Rechercher dans le site', 'value' => $rewrite . 'search' ]; $children[] = [ 'title' => 'Plan du site', 'value' => $rewrite . 'sitemap' ]; $parents[] = [ 'title' => 'Pages spéciales', 'value' => '#', 'menu' => $children ]; for ($i = 0; $i < 3; $i++) { if (file_put_contents('core/vendor/tinymce/link_list.json', json_encode($parents, JSON_UNESCAPED_UNICODE), LOCK_EX) !== false) { break; } usleep(10000); } } public function updateSitemap($full = false) { $outputDir = __DIR__; $baseUrl = rtrim(Helper::baseUrl(false), '/') . '/'; $datetime = new DateTime('now', new DateTimeZone('UTC')); $timezone = $this->getData(['config', 'timezone']); $savedSiteContent = self::$siteContent; $this->tinyMcePages(); $defaultLang = $savedSiteContent; foreach (self::$languages as $key => $value) { if (is_dir(self::DATA_DIR . $key) && file_exists(self::DATA_DIR . $key . '/.default')) { $defaultLang = $key; break; } } if ($full) { $langs = []; foreach (self::$languages as $key => $value) { if (is_dir(self::DATA_DIR . $key)) { $langs[] = $key; } } } else { $langs = [$defaultLang]; if ($savedSiteContent !== $defaultLang) { $langs[] = $savedSiteContent; } } $flag = false; $fillSitemap = function ($gen, $lParam) use ($datetime, $timezone, &$flag) { foreach ($this->getHierarchy() as $parentPageId => $childrenPageIds) { if ( $this->getData(['page', $parentPageId, 'role']) !== 0 || $this->getData(['page', $parentPageId, 'block']) === 'bar' ) { continue; } if ($this->getData(['page', $parentPageId, 'disable']) !== true) { $url = '/' . $parentPageId; $gen->addUrl($url . $lParam, $datetime); $flag = true; } if ( $this->getData(['page', $parentPageId, 'moduleId']) === 'blog' && !empty($this->getData(['module', $parentPageId, 'posts'])) ) { foreach ($this->getData(['module', $parentPageId, 'posts']) as $articleId => $article) { if ($article['state'] === true) { $date = (int) $article['publishedOn']; $dt = new DateTime('@' . $date); $dt->setTimezone(new DateTimeZone($timezone)); $gen->addUrl('/' . $parentPageId . '/' . $articleId . $lParam, $dt); } } } foreach ($childrenPageIds as $childKey) { if ( $this->getData(['page', $childKey, 'role']) !== 0 || $this->getData(['page', $childKey, 'disable']) === true ) { continue; } $gen->addUrl('/' . $childKey . $lParam, $datetime); $flag = true; if ( $this->getData(['page', $childKey, 'moduleId']) === 'blog' && !empty($this->getData(['module', $childKey, 'posts'])) ) { foreach ($this->getData(['module', $childKey, 'posts']) as $articleId => $article) { if ($article['state'] === true) { $date = (int) $article['publishedOn']; $dt = new DateTime('@' . $date); $dt->setTimezone(new DateTimeZone($timezone)); $gen->addUrl('/' . $childKey . '/' . $articleId . $lParam, $dt); } } } } } $gen->flush(); $gen->finalize(); }; foreach ($langs as $lang) { self::$siteContent = $lang; $this->jsonDB($lang, ['page', 'module', 'locale']); $this->buildHierarchy(); $lParam = file_exists(self::DATA_DIR . $lang . '/.default') ? '' : '?l=' . $lang; $gen = new \Icamys\SitemapGenerator\SitemapGenerator($baseUrl, $outputDir); $gen->setMaxUrlsPerSitemap(50000); $gen->setSitemapFileName('sitemap-' . $lang . '.xml'); $gen->setSitemapIndexFileName('sitemap-' . $lang . '-index.xml'); $fillSitemap($gen, $lParam); } self::$siteContent = $savedSiteContent; $this->jsonDB($savedSiteContent, ['page', 'module', 'locale']); $this->buildHierarchy(); if (!$flag) { return false; } $indexXml = '<?xml version="1.0" encoding="UTF-8"?>' . PHP_EOL; $indexXml .= '<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' . PHP_EOL; foreach (glob(__DIR__ . '/sitemap-*.xml') as $file) { if (str_contains($file, '-index.xml')) { continue; } $lastmod = date('Y-m-d', filemtime($file)); $indexXml .= " <sitemap>\n"; $indexXml .= "  <loc>" . $baseUrl . basename($file) . "</loc>\n"; $indexXml .= "  <lastmod>{$lastmod}</lastmod>\n"; $indexXml .= " </sitemap>\n"; } $indexXml .= '</sitemapindex>'; file_put_contents(__DIR__ . '/sitemap.xml', $indexXml); if ($this->getData(['config', 'seo', 'robots']) === true) { file_put_contents( __DIR__ . '/robots.txt', "User-agent: *\nAllow: /\nSitemap: {$baseUrl}sitemap.xml" ); } else { file_put_contents(__DIR__ . '/robots.txt', "User-agent: *\nDisallow: /"); } return (file_exists(__DIR__ . '/sitemap.xml')); } private function addTinyMceChildren(&$menu, $childrenPageIds, $rewrite, $depth = 1) { $maxDepth = 3; if ($depth >= $maxDepth) { return; } foreach ($childrenPageIds as $childId) { if ($this->getData(['page', $childId])) { $alreadyExists = false; foreach ($menu as $existingItem) { if ($existingItem['value'] === $rewrite . $childId) { $alreadyExists = true; break; } } if ($alreadyExists) { continue; } $indent = str_repeat('── ', $depth); $childEntry = [ 'title' => $indent . html_entity_decode($this->getData(['page', $childId, 'title']), ENT_QUOTES), 'value' => $rewrite . $childId, 'menu' => [] ]; $grandChildren = []; foreach ($this->getData(['page']) as $pageId => $pageData) { if ($pageData['parentPageId'] === $childId) { $grandChildren[] = $pageId; } } if (!empty($grandChildren)) { $this->addTinyMceChildren($childEntry['menu'], $grandChildren, $rewrite, $depth + 1); } $menu[] = $childEntry; } } } }
